const COLORS={proofs:'#c49b42',home:'#8b60d1',orders:'#8354cb',production:'#19b6b4',myWork:'#5096e8',catalog:'#5d91e5',calculators:'#f0a04f',inventory:'#f09c50',purchases:'#5c9be8',clients:'#d879ac',employees:'#ce78a2',branches:'#7487df',reviews:'#e7b24b',reports:'#55b894',settings:'#8b8fa2',activity:'#6babb9'};
