function canRoute(route){if(!actor())return false;const p={orders:null,order:null,proofs:'manage_orders',newOrder:'manage_orders',production:'manage_production',inventory:'manage_inventory',purchases:'request_purchase',employees:'manage_team',branches:'manage_branches',clients:'manage_orders',reviews:'view_reviews',reports:'view_reports',activity:'view_reports',settings:'manage_settings',calculators:'view_financials'}[route];return !p||perm(p);}
